"""A small deterministic text-metrics skill authored during self-extension."""

from typing import Any

from ourob.skills.base import Skill, SkillContext, skill
from ourob.state.model import SkillResult


@skill(
    "text_metrics",
    title="Text metrics",
    description="Count characters, whitespace-delimited words, and lines in text.",
    params={"text": {"type": "str", "required": True, "desc": "text to measure"}},
)
class TextMetrics(Skill):
    def run(self, ctx: SkillContext, **kwargs: Any) -> SkillResult:
        text = str(kwargs["text"])
        data = {"characters": len(text), "words": len(text.split()), "lines": len(text.splitlines())}
        return SkillResult(
            ok=True,
            output=f"{data['words']} words, {data['lines']} lines",
            data=data,
        )
